dict(en="can-ai-predict-crypto-prices", slug="kan-ai-cryptokoersen-voorspellen", tag="AI",
 title="Kan AI cryptokoersen voorspellen? We testten het 120 keer",
 desc="We lieten het open-source model Kronos 120 momenten uit het verleden voorspellen voor BTC, ETH, SOL, DOGE, XRP en PEPE. Dit is de eerlijke score.",
 body=[
 ("quick", "Niet betrouwbaar. In onze test van 120 momenten uit het verleden had het open-source model Kronos de richting na 24 uur 68 keer juist (57%). Een muntje opgooien geeft 50%. En gewoon gokken dat \"de prijs gelijk blijft\" zat gemiddeld dichter bij dan de AI."),
 ("p", "Reclame voor \"AI-tradingbots\" belooft veel. Wij wilden een eerlijke test die je zelf kunt nakijken. Daarom gebruikten we een echt onderzoeksmodel en voorspelden we alleen momenten uit het verleden, waarvan we al weten wat er gebeurde."),
 ("h2", "Hoe de test werkt"),
 ("ol", ["We nemen publieke koersdata per uur (geen account, geen sleutels) voor zes munten: BTC, ETH, SOL, DOGE, XRP en PEPE.",
         "We kiezen 20 momenten per munt. Het model ziet de 360 uur ervoor en niets erna.",
         "Kronos-small, een open model dat getraind is op grafieken van veel beurzen, schrijft de volgende 24 uur, zes keer.",
         "We vergelijken zijn middelste gok met wat er echt gebeurde, en met een luie gok \"geen verandering\"."]),
 ("h2", "Het resultaat"),
 ("ul", ["**Richting juist:** 68 van de 120 momenten (57%).",
         "**Gemiddelde fout van de AI:** ongeveer 4,4% van de prijs na 24 uur.",
         "**Gemiddelde fout van \"geen verandering\":** ongeveer 2,9%. De luie gok won.",
         "De cijfers schuiven elke week een beetje, omdat een script de test opnieuw doet met nieuwe momenten."]),
 ("h2", "Waarom dit belangrijk is"),
 ("p", "57% klinkt als een voordeel, maar op 120 momenten kan dat makkelijk geluk zijn, en handelskosten eten kleine voordelen snel op. Markten reageren op nieuws dat in geen enkele grafiek staat. Wie je een zekere AI-voorspelling verkoopt, verkoopt een verhaal."),
 ("h2", "Probeer zelf de AI te verslaan"),
 ("p", "In het [Kronos Lab](/kronos.html) zie je een echte grafiek uit het verleden. Eerst gok jij hoger of lager, dan gokt het model, en dan zie je wat er echt gebeurde. Wil je zelf leren grafieken lezen? Begin met [Chart School](/chart.html)."),
 ("note", "Alleen momenten uit het verleden. Geen live voorspellingen, geen signalen, nooit over $MAIGA. Geen financieel advies."),
 ("cta", ("Open het Kronos Lab", "/kronos.html")),
 ],
 faq=[("Versloeg de AI een muntje opgooien?", "Net: 57% juist voor de richting tegenover 50% voor een muntje. Op maar 120 momenten kan dat geluk zijn."),
      ("Welk model werd gebruikt?", "Kronos-small, een open-source model van Shi Yu en collega's (MIT-licentie), gedraaid op een gewone processor in GitHub Actions."),
      ("Kan ik de ruwe resultaten zien?", "Ja. De pagina van het Kronos Lab toont per munt elk moment, de voorspelde band en de echte prijs.")]),

dict(en="what-is-a-honeypot-token", slug="wat-is-een-honeypot-token", tag="Veiligheid",
 title="Wat is een honeypot-token, en hoe herken je er een?",
 desc="Bij een honeypot kun je kopen maar nooit verkopen. Leer de waarschuwingstekens in publieke data voor je geld verliest.",
 body=[
 ("quick", "Een honeypot-token is zo gemaakt dat kopen werkt, maar verkopen mislukt of bijna alles wegbelast. Het duidelijkste publieke teken: veel aankopen en geen verkopen. Check het voor je koopt; achteraf is het te laat."),
 ("h2", "Hoe een honeypot werkt"),
 ("p", "De truc zit in de regels van de token of in hoe de pool is opgezet. De grafiek gaat alleen omhoog, omdat niemand kan verkopen. Die stijgende grafiek is het lokaas. Mensen kopen, proberen te verkopen, en ontdekken dat het niet gaat."),
 ("h2", "Waarschuwingstekens die je kunt zien"),
 ("ul", ["**Aankopen maar geen verkopen** in de laatste 24 uur, bijvoorbeeld 58 aankopen en 0 verkopen.",
         "**Een vlag van een databron:** GeckoTerminal markeert sommige tokens als mogelijke honeypot.",
         "**Freeze-recht staat nog aan:** de maker kan je account bevriezen, zodat je je tokens niet kunt bewegen.",
         "**De prijs gaat alleen omhoog** in een perfecte lijn, vaak bij een gloednieuwe pool met weinig liquiditeit."]),
 ("h2", "Wat je kunt doen"),
 ("ol", ["Plak het adres in de gratis [Token Checkup](/hq.html#checkup) en lees elke vlag.",
         "Bekijk de recente transacties in een explorer: zie je echte verkopen door verschillende wallets?",
         "Wil je het toch proberen, gebruik dan nooit geld dat je niet kunt missen."]),
 ("note", "Geen enkele publieke controle vangt elke honeypot. Alleen uitleg, geen financieel advies."),
 ("cta", ("Check een token", "/hq.html#checkup")),
 ],
 faq=[("Krijg ik mijn geld terug van een honeypot?", "Meestal niet. Blockchaintransacties kun je niet terugdraaien. Voorkomen is de enige echte bescherming."),
      ("Betekent 'geen honeypot-vlag' dat het veilig is?", "Nee. Het betekent alleen dat de databron geen teken zag dat verkopen geblokkeerd is.")]),

dict(en="how-to-read-candlestick-charts", slug="candlestick-grafieken-lezen", tag="Leren",
 title="Candlestick-grafieken lezen: een gids voor beginners",
 desc="Candles, volume, voortschrijdend gemiddelde en RSI in gewone woorden uitgelegd, met gratis oefengrafieken met verzonnen data.",
 body=[
 ("quick", "Elke candle toont vier prijzen voor één periode: opening, hoogste, laagste en slot. Een groene candle sloot hoger dan hij opende, een rode lager. Volume toont hoeveel er verhandeld werd. Leer de vormen op oefengrafieken voor je naar echt geld kijkt."),
 ("h2", "Eén candle, vier prijzen"),
 ("ul", ["**Body:** het deel tussen opening en slot.",
         "**Lontjes (wicks):** de dunne lijnen erboven en eronder, met de hoogste en laagste prijs.",
         "**Kleur:** groen (of hol) als hij hoger sloot, rood als hij lager sloot."]),
 ("h2", "Volume"),
 ("p", "De staafjes onder de grafiek tonen hoeveel er verhandeld werd. Een grote beweging op heel weinig volume is makkelijk te duwen en makkelijk terug te draaien. Een beweging met sterk volume betekent dat meer mensen meededen."),
 ("h2", "Voortschrijdend gemiddelde"),
 ("p", "Een voortschrijdend gemiddelde is het gemiddelde slot van de laatste periodes, getekend als een gladde lijn. Het toont de algemene richting en filtert wat ruis weg. Het loopt altijd achter op de prijs."),
 ("h2", "RSI"),
 ("p", "RSI is een getal van 0 tot 100 dat recente stijgingen vergelijkt met recente dalingen. Boven 70 heet vaak overkocht, onder 30 oververkocht. Het beschrijft het verleden; het is geen voorspelling."),
 ("h2", "De pump-and-dump-vorm"),
 ("p", "Een plotse verticale stijging op weinig volume, gevolgd door een lange rode daling, is de klassieke pump-and-dump. Late kopers betalen de winst van de vroege verkopers."),
 ("h2", "Oefen zonder risico"),
 ("p", "[Chart School](/chart.html) heeft zeven korte lessen en een spel \"raad de volgende candle\" op verzonnen oefengrafieken, dus niets op de pagina is een signaal. Test jezelf daarna tegen een AI in het [Kronos Lab](/kronos.html)."),
 ("cta", ("Open Chart School", "/chart.html")),
 ]),

dict(en="how-does-a-blockchain-work", slug="hoe-werkt-een-blockchain", tag="Leren",
 title="Hoe werkt een blockchain? Bouw er een in je browser",
 desc="Hashes, blokken, minen en waarom je de geschiedenis niet kunt veranderen, uitgelegd met een mini-blockchain die je zelf kunt breken.",
 body=[
 ("quick", "Een blockchain is een lijst van blokken waarbij elk blok de vingerafdruk (hash) van het vorige blok bewaart. Verander één letter in een oud blok, en zijn vingerafdruk verandert, waardoor elk blok erna breekt. Daarom is de geschiedenis moeilijk te herschrijven."),
 ("h2", "Stap 1: de vingerafdruk"),
 ("p", "Een hashfunctie zoals SHA-256 maakt van elke tekst een code met een vaste lengte. Verander één letter en de code verandert volledig. Je kunt niet terugrekenen van de code naar de tekst."),
 ("h2", "Stap 2: blokken verbonden door vingerafdrukken"),
 ("p", "Elk blok bevat wat data, een getal dat de nonce heet, en de hash van het vorige blok. Omdat elk blok naar het vorige wijst, vormen de blokken een ketting."),
 ("h2", "Stap 3: minen"),
 ("p", "Bij proof-of-work-ketens zoals Bitcoin telt een blok pas als zijn hash begint met een bepaald aantal nullen. Miners proberen nonce na nonce tot ze er een vinden. Dat kost werk, en dat werk opnieuw doen voor veel blokken kost nog meer."),
 ("h2", "Stap 4: probeer vals te spelen"),
 ("p", "Pas een oud blok aan en je ziet zijn hash veranderen en elk blok erna ongeldig worden. Om dat te herstellen moet je ze allemaal opnieuw minen, sneller dan iedereen. Op een groot netwerk is dat praktisch onmogelijk."),
 ("note", "Solana gebruikt een ander systeem (proof of stake met proof of history), maar het idee van blokken verbonden door hashes is hetzelfde."),
 ("p", "Open de [Mini-Chain](/chain.html), typ wat je wilt, mine een blok, verander dan één letter en kijk hoe de ketting breekt. Er wordt niets verstuurd en er zijn geen echte munten bij betrokken."),
 ("cta", ("Open de Mini-Chain", "/chain.html")),
 ]),

dict(en="is-solana-quantum-safe", slug="is-solana-veilig-tegen-quantumcomputers", tag="Leren",
 title="Is Solana veilig tegen quantumcomputers? Eenvoudig uitgelegd",
 desc="Waarom de handtekeningen van vandaag ooit gebroken kunnen worden door een grote quantumcomputer, wat post-quantum handtekeningen zijn, en hoe je ze uitprobeert.",
 body=[
 ("quick", "Niet uit zichzelf. Solana-wallets tekenen met Ed25519, en een quantumcomputer die groot genoeg is zou dat kunnen breken met het algoritme van Shor. Zo'n computer bestaat vandaag niet. Post-quantum handtekeningen zoals ML-DSA (een Amerikaanse standaard sinds augustus 2024) zijn gemaakt om die aanval te weerstaan."),
 ("h2", "Wat een handtekening doet"),
 ("p", "Als je munten verstuurt, tekent je wallet de transactie met je privésleutel. Iedereen kan de handtekening controleren met je publieke sleutel, maar niemand kan ze vervalsen zonder de privésleutel."),
 ("h2", "De quantumdreiging"),
 ("p", "Het algoritme van Shor, op een grote en stabiele quantumcomputer, zou voor Ed25519 en gelijkaardige systemen een privésleutel kunnen afleiden uit een publieke sleutel. De quantummachines van vandaag zijn daar veel te klein en te onstabiel voor. Niemand weet precies wanneer, of of, dat verandert."),
 ("h2", "Post-quantum handtekeningen"),
 ("ul", ["**ML-DSA-65:** de officiële Amerikaanse standaard (NIST FIPS 204, augustus 2024). Grotere sleutels en handtekeningen: ongeveer 1.952 en 3.309 bytes.",
         "**Falcon-512:** kleinere handtekeningen, maar ingewikkelder om te bouwen.",
         "**Ed25519 vandaag:** sleutels van 32 bytes, handtekeningen van 64 bytes. Klein en snel, maar niet quantumveilig."]),
 ("h2", "Wat het betekent voor $MAIGA"),
 ("p", "$MAIGA is een token op Solana, dus precies even quantumveilig als Solana zelf. Stapt Solana over op post-quantum handtekeningen, dan volgen de tokens erop."),
 ("p", "In het [Quantum Lab](/quantum.html) teken je een bericht met Ed25519 en met de post-quantum algoritmes, gewoon in je browser, en vergelijk je grootte en snelheid."),
 ("cta", ("Open het Quantum Lab", "/quantum.html")),
 ],
 faq=[("Kan een quantumcomputer vandaag crypto stelen?", "Nee. De huidige quantumcomputers zijn veel te klein om Ed25519 te breken."),
      ("Is $MAIGA quantumveilig?", "Alleen even veilig als Solana. Het heeft geen eigen extra quantumbescherming.")]),

